list.cssText:
@keyframes beam { 
  0% { transform: translateX(-4%) rotate(-1deg); }
  100% { transform: translateX(5%) rotate(1.5deg); }
}

@keyframes leaves { 
  0% { transform: translate(0px, 0px) rotate(0deg); }
  50% { transform: translate(2%, -1.5%) rotate(1.5deg); }
  100% { transform: translate(-1.5%, 1%) rotate(-1deg); }
}

@keyframes passIn { 
  0% { transform: translateY(-30px) rotateX(35deg) rotateZ(-6deg); opacity: 0; }
}

@keyframes live { 
  0% { box-shadow: rgba(245, 160, 31, 0.6) 0px 0px 0px 0px; }
  70% { box-shadow: rgba(245, 160, 31, 0) 0px 0px 0px 7px; }
  100% { box-shadow: rgba(245, 160, 31, 0) 0px 0px 0px 0px; }
}

@keyframes penWrite { 
  0% { transform: none; }
  20% { transform: translate(-6px, -4px) rotate(-3deg); }
  45% { transform: translate(4px, 2px) rotate(1deg); }
  70% { transform: translate(-3px, -2px) rotate(-2deg); }
  100% { transform: none; }
}

@keyframes markIn { 
  0% { transform: translate(-50%, -50%) scale(0.6) rotate(-10deg); opacity: 0; }
}

@keyframes tw { 
  0%, 100% { opacity: 0; transform: translate(-50%,-50%) scale(calc(var(--z)*.3)) rotate(0); }
  50% { opacity: 1; transform: translate(-50%,-50%) scale(var(--z)) rotate(45deg); }
}

@keyframes penSign { 
  0% { transform: rotate(-4deg); }
  15% { transform: translate(-40px, -46px) rotate(-14deg); }
  35% { transform: translate(-20px, -40px) rotate(-10deg); }
  55% { transform: translate(10px, -44px) rotate(-14deg); }
  75% { transform: translate(40px, -40px) rotate(-10deg); }
  100% { transform: rotate(-4deg); }
}

@keyframes penW { 
  0%, 100% { transform: rotate(-8deg) translateX(6px); }
  25% { transform: rotate(-18deg) translate(-6px, -4px); }
  50% { transform: rotate(-4deg) translate(10px, 2px); }
  75% { transform: rotate(-16deg) translate(-2px, -3px); }
}

@keyframes penW2 { 
  0%, 100% { transform: none; }
  25% { transform: translate(-4px, -3px) rotate(-1.5deg); }
  50% { transform: translate(6px, 1px) rotate(0.8deg); }
  75% { transform: translate(-2px, -2px) rotate(-1deg); }
}

@keyframes mk { 
  0% { opacity: 0; transform: translate(0px, 0px) rotate(-24deg); }
  20% { opacity: 1; }
  100% { opacity: 1; transform: translate(120px, 24px) rotate(-24deg); }
}

@keyframes tabIn { 
  0% { opacity: 0; transform: translateY(6px); }
  100% { opacity: 1; transform: none; }
}

@keyframes ty { 
  0%, 100% { opacity: 0.25; transform: translateY(0px); }
  50% { opacity: 1; transform: translateY(-3px); }
}

@keyframes burst { 
  0% { opacity: 1; transform: rotate(var(--a)) translateY(-30px); }
  100% { opacity: 0; transform: rotate(var(--a)) translateY(-70px); }
}

@keyframes ssw { 
  0% { transform: scale(0.55); opacity: 1; }
  100% { transform: scale(1.15); opacity: 0; }
}

@keyframes bxClip { 
  0% { clip-path: circle(0px at 22% 6%); }
  10% { clip-path: circle(58px at 22% 6%); }
  35% { clip-path: circle(58px at 72% 26%); }
  60% { clip-path: circle(58px at 30% 52%); }
  82% { clip-path: circle(58px at 70% 82%); }
  92% { clip-path: circle(58px at 55% 92%); opacity: 1; }
  100% { clip-path: circle(58px at 55% 92%); opacity: 0; }
}

@keyframes bxRing { 
  0% { left: 22%; top: 6%; opacity: 0; transform: scale(0.6); }
  10% { left: 22%; top: 6%; opacity: 1; transform: none; }
  35% { left: 72%; top: 26%; }
  60% { left: 30%; top: 52%; }
  82% { left: 70%; top: 82%; }
  92% { left: 55%; top: 92%; opacity: 1; }
  100% { left: 55%; top: 92%; opacity: 0; transform: scale(1.15); }
}

@keyframes fxb { 
  0% { opacity: 1; transform: translateY(-40px); }
  90% { opacity: 1; }
  100% { opacity: 0; transform: translateY(320px); }
}

@keyframes mmp { 
  0% { opacity: 0.2; transform-box: fill-box; transform-origin: center center; transform: scale(0.6); }
  100% { opacity: 1; transform: scale(1.1); }
}

@keyframes lxBeam { 
  0% { transform: translateY(-30px); }
  60% { transform: translateY(130px); }
  100% { transform: translateY(130px); opacity: 0; }
}

@keyframes xvHl { 
  0%, 30% { transform: scaleX(0); }
  45%, 90% { transform: scaleX(1); }
  100% { transform: scaleX(1); opacity: 0; }
}

@keyframes xvBeam { 
  0% { transform: translateY(-24px); }
  55% { transform: translateY(140px); }
  100% { transform: translateY(140px); }
}

@keyframes xvTag { 
  0%, 35% { opacity: 0; transform: scale(0.8); }
  45%, 90% { opacity: 1; transform: none; }
  100% { opacity: 0; }
}

@keyframes stWalk { 
  0% { transform: translate(180px, 462px) scale(0.74); }
  12% { transform: translate(182px, 440px) scale(0.72); }
  26% { transform: translate(186px, 420px) scale(0.68); }
  40% { transform: translate(175px, 392px) scale(0.62); }
  54% { transform: translate(185px, 364px) scale(0.56); }
  68% { transform: translate(176px, 338px) scale(0.5); }
  84% { transform: translate(184px, 314px) scale(0.45); }
  100% { transform: translate(180px, 298px) scale(0.42); }
}

@keyframes stLine3 { 
  0% { opacity: 0; transform: translateY(10px); }
  25%, 100% { opacity: 1; transform: none; }
}

@keyframes stLine { 
  0% { opacity: 0; transform: translateY(10px); }
  20%, 75% { opacity: 1; transform: none; }
  100% { opacity: 0; transform: translateY(-8px); }
}

@keyframes stRays { 
  0% { transform: rotate(-4deg); }
  50% { transform: rotate(4deg); }
  100% { transform: rotate(-4deg); }
}

@keyframes stMote { 
  0% { opacity: 0; transform: translate(0px, 0px); }
  30% { opacity: 0.9; }
  100% { opacity: 0; transform: translate(var(--x),-90px); }
}

@keyframes stWalk2 { 
  0% { transform: translate(180px, 518px) scale(0.6); }
  14% { transform: translate(182px, 470px) scale(0.52); }
  30% { transform: translate(184px, 440px) scale(0.46); }
  45% { transform: translate(177px, 410px) scale(0.4); }
  60% { transform: translate(184px, 380px) scale(0.35); }
  74% { transform: translate(177px, 352px) scale(0.31); }
  88% { transform: translate(183px, 326px) scale(0.27); }
  100% { transform: translate(180px, 304px) scale(0.24); }
}

@keyframes stDot { 
  0% { opacity: 0; transform: scale(0.2); }
  60% { opacity: 0.9; }
  100% { opacity: 0.42; }
}

@keyframes stPing { 
  0% { transform: scale(0.4); opacity: 1; }
  100% { transform: scale(2.4); opacity: 0; }
}

@keyframes stBeamIn { 
  0% { opacity: 0; transform: scaleY(0.2); }
  100% { opacity: 0.7; transform: none; }
}

@keyframes stSpotIn { 
  0% { opacity: 0; transform: scale(0.3); }
  100% { opacity: 1; transform: none; }
}

@keyframes stRip { 
  0% { opacity: 0.9; transform: scale(0.5); }
  100% { opacity: 0; transform: scale(4.2); }
}

@keyframes stOne { 
  0% { transform: translate(180px, 498px) scale(0.52); }
  45% { transform: translate(181px, 470px) scale(0.52) rotate(0.8deg); }
  100% { transform: translate(180px, 450px) scale(0.5); }
}

@keyframes stLine2 { 
  0% { opacity: 0; transform: translateY(10px); }
  20%, 80% { opacity: 1; transform: none; }
  100% { opacity: 0; }
}

@keyframes stOut { 
  0% { transform: translate(180px, 482px) scale(0.5); }
  35% { transform: translate(182px, 462px) scale(0.5) rotate(1deg); }
  100% { transform: translate(180px, 430px) scale(0.47); }
}

@keyframes stFlagUp { 
  0% { opacity: 1; transform: translateY(26px); }
  100% { opacity: 1; transform: none; }
}

@keyframes s4Push { 
  0% { transform: scale(1.06) translateY(10px); }
  100% { transform: scale(1) translateY(0px); }
}

@keyframes s4Col { 
  100% { opacity: 1; transform: none; filter: none; }
}

@keyframes s4Lit { 
  0% { opacity: 0; }
  40% { opacity: 1; filter: brightness(1.35); }
  100% { opacity: 1; filter: none; }
}

@keyframes s4Glint { 
  0% { opacity: 0; transform: skewX(-16deg) translateX(40px); }
  15% { opacity: 0.75; }
  85% { opacity: 0.75; }
  100% { opacity: 0; transform: skewX(-16deg) translateX(330px); }
}

@keyframes s4Flag { 
  0% { opacity: 0; transform: translateY(30px) scaleY(0.2); }
  25% { opacity: 1; }
  100% { opacity: 1; transform: none; }
}

@keyframes s4Ring { 
  0% { opacity: 0.9; transform: scale(0.6); }
  100% { opacity: 0; transform: scale(5); }
}

@keyframes s4Step { 
  0% { transform: translate(180px, 478px) scale(0.5); }
  38% { transform: translate(181.5px, 458px) scale(0.5) rotate(0.8deg); }
  100% { transform: translate(180px, 432px) scale(0.47); }
}

@keyframes s4Bok { 
  0% { opacity: 0; transform: translate(0px, 0px); }
  30% { opacity: 0.55; }
  100% { opacity: 0; transform: translate(var(--dx),-120px); }
}

@keyframes s4Type { 
  0% { opacity: 0; filter: blur(10px); letter-spacing: 0.12em; }
  22% { opacity: 1; filter: blur(0px); letter-spacing: 0.01em; }
  78% { opacity: 1; filter: blur(0px); }
  100% { opacity: 0; filter: blur(6px); }
}

@keyframes s4Type { 
  0% { opacity: 0; filter: blur(8px); letter-spacing: 0.2em; }
  25% { opacity: 1; filter: blur(0px); letter-spacing: 0.04em; }
  80% { opacity: 1; filter: blur(0px); }
  100% { opacity: 0; filter: blur(6px); }
}

@keyframes x4Hl { 
  0%, 25% { transform: scaleX(0); }
  40%, 88% { transform: scaleX(1); }
  100% { transform: scaleX(1); opacity: 0; }
}

@keyframes n2In { 
  0% { opacity: 0; transform: translateY(4px); }
  100% { opacity: 1; transform: none; }
}

@keyframes pmIn { 
  100% { clip-path: circle(150% at var(--x,50%) var(--y,60%)); }
}

@keyframes pmOut { 
  0% { clip-path: circle(150% at 50% 50%); opacity: 1; }
  100% { clip-path: circle(150% at 50% 50%); opacity: 0; transform: scale(1.06); }
}

@keyframes pmRing { 
  0% { transform: scale(0.85); opacity: 1; }
  100% { transform: scale(1.5); opacity: 0; }
}

@keyframes pmSp { 
  0% { opacity: 0; transform: translate(0px, 0px) scale(0.2) rotate(0deg); }
  20% { opacity: 1; }
  100% { opacity: 0; transform: translate(var(--tx),var(--ty)) scale(1) rotate(160deg); }
}
